public class InnerMemorySemanticOverrideFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride>
{

    internal InnerMemorySemanticOverrideConsolidationConfigurationInputFactory ConsolidationFactory { get; set; }

    internal InnerMemorySemanticOverrideExtractionConfigurationInputFactory ExtractionFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride Create()
    {
        var semanticOverrideResult = CreateSemanticOverride();
        factoryAction?.Invoke(semanticOverrideResult);

        return semanticOverrideResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride CreateSemanticOverride()
    {
        var semanticOverrideResult = new Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride();

        return semanticOverrideResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.SemanticOverride result)
    {
        base.CreateChildren(result);

        result.Consolidation ??= ConsolidationFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
    }

} // End Of Class

